1	// Core static analysis: registry/inheritance, entry points, reachability
2	// via the intra-contract call graph, and the three audit rules.
3	
4	export const RULES = {
5	  DELEGATECALL_UNTRUSTED_TARGET: { severity: 'high' },
6	  UNCHECKED_EXTERNAL_CALL: { severity: 'medium' },
7	  STATE_UPDATE_AFTER_CALL: { severity: 'high' },
8	};
9	
10	const LOW_LEVEL_CALLS = new Set(['call', 'staticcall', 'send', 'transfer']);
11	const DELEGATE_CALLS = new Set(['delegatecall']);
12	const ALL_LOW_LEVEL = new Set([...LOW_LEVEL_CALLS, ...DELEGATE_CALLS]);
13	const BUILTIN_CALLS = new Set([
14	  'require', 'assert', 'revert', 'keccak256', 'sha256', 'ripemd160',
15	  'ecrecover', 'addmod', 'mulmod', 'blockhash', 'selfdestruct', 'suicide',
16	  'gasleft', 'blake2f160',
17	]);
18	
19	// ---- descriptors -----------------------------------------------------------
20	
21	const methodKey = (name, arity) => `${name}/${arity}`;
22	const descKey = (d) => `${d.file}::${d.contract || ''}::${d.kind}:${d.name}/${d.arity}`;
23	const entryKey = (d) => `${d.contract || ''}:${d.kind}:${d.name}/${d.arity}`;
24	
25	function descriptorFor(node, file, contractName, arity) {
26	  return {
27	    file,
28	    contract: contractName,
29	    name: node.functionKind === 'function' ? node.name : node.functionKind,
30	    kind: node.functionKind,
31	    arity,
32	    visibility: node.visibility,
33	  };
34	}
35	const stripNode = (d) => ({ file: d.file, contract: d.contract, name: d.name, kind: d.kind });
36	
37	// ---- expression walking ----------------------------------------------------
38	
39	const SKIP = Symbol('skip-children');
40	
41	function walkExpr(node, cb) {
42	  if (!node || typeof node !== 'object') return;
43	  cb(node);
44	  switch (node.kind) {
45	    case 'binary': walkExpr(node.left, cb); walkExpr(node.right, cb); break;
46	    case 'unary': walkExpr(node.operand, cb); break;
47	    case 'assign': walkExpr(node.target, cb); walkExpr(node.value, cb); break;
48	    case 'conditional': walkExpr(node.test, cb); walkExpr(node.cons, cb); walkExpr(node.alt, cb); break;
49	    case 'member': walkExpr(node.object, cb); break;
50	    case 'index': walkExpr(node.object, cb); if (node.index) walkExpr(node.index, cb); break;
51	    case 'call':
52	      walkExpr(node.callee, cb);
53	      for (const a of node.args || []) walkExpr(a, cb);
54	      for (const o of node.options || []) walkExpr(o.value, cb);
55	      break;
56	    case 'tuple': for (const it of node.items || []) walkExpr(it, cb); break;
57	    case 'newExpr': break;
58	    case 'structLiteral': for (const f of node.fields || []) walkExpr(f.value, cb); break;
59	    default: break;
60	  }
61	}
62	
63	// Contextual expression walk: 'normal' | 'check' (boolean control position)
64	// | 'drop' (result value is irrelevant, e.g. returned/assigned).
65	function walkExprCtx(node, ctx, cb) {
66	  if (!node || typeof node !== 'object') return;
67	  if (cb(node, ctx) === SKIP) return;
68	  switch (node.kind) {
69	    case 'binary':
70	      if (node.op === '&&' || node.op === '||') {
71	        walkExprCtx(node.left, 'check', cb);
72	        walkExprCtx(node.right, 'check', cb);
73	      } else {
74	        walkExprCtx(node.left, ctx, cb);
75	        walkExprCtx(node.right, ctx, cb);
76	      }
77	      break;
78	    case 'unary':
79	      walkExprCtx(node.operand, node.op === '!' ? 'check' : ctx, cb);
80	      break;
81	    case 'assign':
82	      walkExprCtx(node.target, 'drop', cb);
83	      walkExprCtx(node.value, ctx, cb);
84	      break;
85	    case 'conditional':
86	      walkExprCtx(node.test, 'check', cb);
87	      walkExprCtx(node.cons, ctx, cb);
88	      walkExprCtx(node.alt, ctx, cb);
89	      break;
90	    case 'member': walkExprCtx(node.object, ctx, cb); break;
91	    case 'index': walkExprCtx(node.object, ctx, cb); if (node.index) walkExprCtx(node.index, ctx, cb); break;
92	    case 'call':
93	      if (node.callee.kind === 'ident' &&
94	          (node.callee.name === 'require' || node.callee.name === 'assert')) {
95	        (node.args || []).forEach((a, i) => walkExprCtx(a, i === 0 ? 'check' : 'drop', cb));
96	      } else {
97	        walkExprCtx(node.callee, ctx, cb);
98	        for (const a of node.args || []) walkExprCtx(a, 'normal', cb);
99	        for (const o of node.options || []) walkExprCtx(o.value, 'normal', cb);
100	      }
101	      break;
102	    case 'tuple': for (const it of node.items || []) walkExprCtx(it, ctx, cb); break;
103	    case 'structLiteral': for (const f of node.fields || []) walkExprCtx(f.value, ctx, cb); break;
104	    default: break;
105	  }
106	}
107	
108	function walkStatement(stmt, cb) {
109	  if (!stmt) return;
110	  cb(stmt);
111	  const rec = (s) => walkStatement(s, cb);
112	  switch (stmt.kind) {
113	    case 'block': (stmt.statements || []).forEach(rec); break;
114	    case 'unchecked': rec(stmt.body); break;
115	    case 'if':
116	      rec(stmt.consequent);
117	      if (stmt.alternate) rec(stmt.alternate);
118	      break;
119	    case 'while': case 'doWhile': rec(stmt.body); break;
120	    case 'for':
121	      if (stmt.init) rec(stmt.init);
122	      rec(stmt.body);
123	      break;
124	    case 'try':
125	      rec(stmt.body);
126	      (stmt.clauses || []).forEach(rec);
127	      break;
128	    default: break;
129	  }
130	}
131	
132	// Iterate every statement (origin annotated), depth-first in source order.
133	function eachStatement(wrapped, cb) {
134	  const rec = (s, origin) => {
135	    cb(s, origin);
136	    switch (s.kind) {
137	      case 'block': case 'unchecked':
138	        (s.kind === 'block' ? s.statements : s.body ? [s.body] : []).forEach((c) => rec(c, origin));
139	        break;
140	      case 'if':
141	        if (s.consequent) rec(s.consequent, origin);
142	        if (s.alternate) rec(s.alternate, origin);
143	        break;
144	      case 'while': case 'doWhile': rec(s.body, origin); break;
145	      case 'for':
146	        if (s.init) rec(s.init, origin);
147	        rec(s.body, origin);
148	        break;
149	      case 'try':
150	        rec(s.body, origin);
151	        (s.clauses || []).forEach((c) => rec(c, origin));
152	        break;
153	      default: break;
154	    }
155	  };
156	  for (const { stmt, origin } of wrapped) rec(stmt, origin);
157	}
158	
159	// Flatten to an ordered list of simple "execution steps" (origin annotated).
160	// Control-flow tests appear as synthetic expression steps in textual order.
161	function linearSteps(wrapped) {
162	  const out = [];
163	  const exprStep = (expr, origin) => ({ stmt: { kind: 'expression', expr }, origin });
164	  const condStep = (expr, origin) => ({ stmt: { kind: '__cond__', expr }, origin });
165	  const rec = (s, origin) => {
166	    switch (s.kind) {
167	      case 'block': (s.statements || []).forEach((c) => rec(c, origin)); return;
168	      case 'unchecked': rec(s.body, origin); return;
169	      case 'if':
170	        if (s.test) out.push(condStep(s.test, origin));
171	        rec(s.consequent, origin);
172	        if (s.alternate) rec(s.alternate, origin);
173	        return;
174	      case 'while':
175	        if (s.test) out.push(condStep(s.test, origin));
176	        rec(s.body, origin);
177	        return;
178	      case 'doWhile':
179	        rec(s.body, origin);
180	        if (s.test) out.push(condStep(s.test, origin));
181	        return;
182	      case 'for':
183	        if (s.init) rec(s.init, origin);
184	        if (s.test) out.push(condStep(s.test, origin));
185	        rec(s.body, origin);
186	        if (s.update) out.push(exprStep(s.update, origin));
187	        return;
188	      case 'try':
189	        // A tried external call is checked: a catch clause handles
190	        // failure, and without one the failure propagates (reverts).
191	        out.push({ stmt: { kind: 'tryCall', expr: s.externalCall,
192	          hasCatch: (s.clauses || []).length > 0 }, origin });
193	        rec(s.body, origin);
194	        (s.clauses || []).forEach((c) => rec(c, origin));
195	        return;
196	      default:
197	        out.push({ stmt: s, origin });
198	    }
199	  };
200	  for (const { stmt, origin } of wrapped) rec(stmt, origin);
201	  return out;
202	}
203	
204	const isLowLevelCall = (expr, set = ALL_LOW_LEVEL) =>
205	  expr && expr.kind === 'call' &&
206	  expr.callee && expr.callee.kind === 'member' &&
207	  set.has(expr.callee.property);
208	
209	// Span covering the dangerous operation: `<target>.<method>` for a
210	// low-level call (excludes the argument list).
211	function operationSpan(callNode) {
212	  const mem = callNode.callee;
213	  return {
214	    startOffset: mem.object.loc.startOffset,
215	    endOffset: mem.propertyLoc.endOffset,
216	    startLine: mem.object.loc.startLine,
217	    startColumn: mem.object.loc.startColumn,
218	    endLine: mem.propertyLoc.endLine,
219	    endColumn: mem.propertyLoc.endColumn,
220	  };
221	}
222	
223	function statementExpressions(stmt) {
224	  const out = [];
225	  switch (stmt.kind) {
226	    case 'expression': if (stmt.expr) out.push(stmt.expr); break;
227	    case 'varDecl': if (stmt.initializer) out.push(stmt.initializer); break;
228	    case 'return': if (stmt.expr) out.push(stmt.expr); break;
229	    case 'emit': if (stmt.expr) out.push(stmt.expr); break;
230	    case 'if': case 'while': case 'doWhile': if (stmt.test) out.push(stmt.test); break;
231	    case '__cond__': out.push(stmt.expr); break;
232	    case 'for':
233	      if (stmt.test) out.push(stmt.test);
234	      if (stmt.update) out.push(stmt.update);
235	      if (stmt.init && stmt.init.kind === 'expression') out.push(stmt.init.expr);
236	      if (stmt.init && stmt.init.kind === 'varDecl' && stmt.init.initializer) out.push(stmt.init.initializer);
237	      break;
238	    default: break;
239	  }
240	  return out;
241	}
242	
243	function lvalueNames(expr) {
244	  if (!expr) return [];
245	  if (expr.kind === 'ident') return [expr.name];
246	  if (expr.kind === 'member' || expr.kind === 'index') return lvalueNames(expr.object);
247	  if (expr.kind === 'tuple') return (expr.items || []).flatMap(lvalueNames);
248	  return [];
249	}
250	
251	// ---- view construction (inheritance + override final declaration) ----------
252	
253	class View {
254	  constructor(desc, registry, linearized, stateVars, methods, modifiers, freeFunctions, entries) {
255	    this.desc = desc;
256	    this.registry = registry;
257	    this.linearized = linearized;
258	    this.stateVars = stateVars;
259	    this.methods = methods;
260	    this.modifiers = modifiers;
261	    this.freeFunctions = freeFunctions;
262	    this.entries = entries;
263	    this._modifierPieces = new Map();
264	  }
265	
266	  resolveMethod(name, arity) {
267	    return this.methods.get(methodKey(name, arity)) ||
268	      this.freeFunctions.get(methodKey(name, arity)) || null;
269	  }
270	
271	  // Body statements with the modifier chain inlined. Rightmost modifier is
272	  // innermost (modA modB => A.pre, B.pre, body, B.post, A.post).
273	  effectiveStatements(desc) {
274	    const node = desc.node;
275	    if (!node.body) return [];
276	    let composed = node.body.statements.map((stmt) => ({ stmt, origin: desc }));
277	    const mods = node.modifiers || [];
278	    for (let i = mods.length - 1; i >= 0; i--) {
279	      const pieces = this.modifierPieces(mods[i]);
280	      if (pieces) composed = [...pieces.pre, ...composed, ...pieces.post];
281	    }
282	    return composed;
283	  }
284	
285	  modifierPieces(name) {
286	    if (this._modifierPieces.has(name)) return this._modifierPieces.get(name);
287	    const mod = this.modifiers.get(name);
288	    if (!mod) { this._modifierPieces.set(name, null); return null; }
289	    this._modifierPieces.set(name, undefined); // recursion guard
290	
291	    const stmts = mod.node.body ? mod.node.body.statements : [];
292	    let pre = [];
293	    let post = [];
294	    let part = 0;
295	    const push = (s) => { (part === 0 ? pre : post).push({ stmt: s, origin: mod }); };
296	    for (const s of stmts) {
297	      if (s.kind === 'placeholder') { part = 1; continue; }
298	      if (s.kind === 'block') { (s.statements || []).forEach(push); continue; }
299	      push(s);
300	    }
301	    for (const innerName of mod.node.modifiers || []) {
302	      const inner = this.modifierPieces(innerName);
303	      if (inner) { pre = [...inner.pre, ...pre]; post = [...post, ...inner.post]; }
304	    }
305	    const pieces = { pre, post };
306	    this._modifierPieces.set(name, pieces);
307	    return pieces;
308	  }
309	}
310	
311	export class Registry {
312	  constructor(parsedFiles) {
313	    this.files = parsedFiles;
314	    this.contractByName = new Map();
315	    this.allContracts = [];
316	    this.freeFunctions = new Map();
317	
318	    for (const { file, ast } of parsedFiles) {
319	      for (const contract of ast.contracts) {
320	        const entry = { file, contract };
321	        this.allContracts.push(entry);
322	        if (!this.contractByName.has(contract.name)) this.contractByName.set(contract.name, []);
323	        this.contractByName.get(contract.name).push(entry);
324	      }
325	      for (const fn of ast.freeFunctions || []) {
326	        const arity = (fn.params || []).length;
327	        this.freeFunctions.set(
328	          methodKey(fn.name, arity),
329	          { ...descriptorFor(fn, file, null, arity), node: fn });
330	      }
331	    }
332	  }
333	
334	  resolveBaseName(name, fromFile) {
335	    return (this.contractByName.get(name) || []).find((c) => c.file === fromFile) ||
336	      (this.contractByName.get(name) || [])[0] || null;
337	  }
338	
339	  buildViews() {
340	    return this.allContracts.map((entry) => this.buildView(entry));
341	  }
342	
343	  buildView(entry) {
344	    const { file, contract } = entry;
345	    // Most-derived-first DFS linearization of declared bases.
346	    const ordered = [];
347	    const seen = new Set();
348	    const visit = (f, c) => {
349	      const k = `${f}::${c.name}`;
350	      if (seen.has(k)) return;
351	      seen.add(k);
352	      ordered.push({ file: f, contract: c });
353	      for (const baseName of c.bases || []) {
354	        const base = this.resolveBaseName(baseName, f);
355	        if (base) visit(base.file, base.contract);
356	      }
357	    };
358	    visit(file, contract);
359	
360	    // Inheritance + override: first (most-derived) declaration wins.
361	    const methods = new Map();
362	    const modifiers = new Map();
363	    const stateVars = new Map();
364	    for (const { file: f, contract: c } of ordered) {
365	      for (const node of c.nodes || []) {
366	        if (node.functionKind === 'modifier') {
367	          if (!modifiers.has(node.name)) {
368	            modifiers.set(node.name, {
369	              file: f, contract: c.name, name: node.name, kind: 'modifier',
370	              arity: (node.params || []).length, node,
371	            });
372	          }
373	          continue;
374	        }
375	        const arity = (node.params || []).length;
376	        const name = node.functionKind === 'function' ? node.name : node.functionKind;
377	        const key = methodKey(name, arity);
378	        if (!methods.has(key)) {
379	          methods.set(key, { ...descriptorFor(node, f, c.name, arity), node });
380	        }
381	      }
382	      for (const sv of c.stateVariables || []) {
383	        if (!stateVars.has(sv.name)) {
384	          stateVars.set(sv.name, {
385	            file: f, contract: c.name, name: sv.name, kind: 'stateVariable',
386	            visibility: sv.visibility, node: sv,
387	          });
388	        }
389	      }
390	    }
391	
392	    const entries = [];
393	    if (contract.kind !== 'library') {
394	      for (const m of methods.values()) {
395	        if (m.kind === 'constructor' || m.kind === 'fallback' || m.kind === 'receive') {
396	          entries.push(m);
397	        } else if (m.kind === 'function' &&
398	                   (m.visibility === 'public' || m.visibility === 'external')) {
399	          entries.push(m);
400	        }
401	      }
402	      for (const sv of stateVars.values()) {
403	        if (sv.visibility === 'public') {
404	          entries.push({ file: sv.file, contract: sv.contract, name: sv.name,
405	            kind: 'getter', arity: 0, node: null });
406	        }
407	      }
408	    }
409	
410	    const desc = { file, contract: contract.name, name: contract.name, kind: 'contract', arity: 0 };
411	    return new View(desc, this, ordered, stateVars, methods, modifiers, this.freeFunctions, entries);
412	  }
413	}
414	
415	// ---- reachability ----------------------------------------------------------
416	
417	function findMethodInContract(view, c, file, name, arity) {
418	  const node = (c.nodes || []).find((fn) =>
419	    (fn.functionKind === 'function' ? fn.name : fn.functionKind) === name &&
420	    (fn.params || []).length === arity && fn.functionKind !== 'modifier');
421	  if (!node) return null;
422	  return { ...descriptorFor(node, file, c.name, arity), node };
423	}
424	
425	function collectEdges(view, desc) {
426	  const edges = [];
427	  const seen = new Set();
428	  const add = (target) => {
429	    if (!target) return;
430	    const k = descKey(target);
431	    if (!seen.has(k)) { seen.add(k); edges.push(target); }
432	  };
433	
434	  const wrapped = view.effectiveStatements(desc);
435	  eachStatement(wrapped, (stmt) => {
436	    for (const expr of statementExpressions(stmt)) {
437	      walkExpr(expr, (n) => {
438	        if (n.kind !== 'call') return;
439	        const callee = n.callee;
440	        const argc = (n.args || []).length;
441	        if (callee.kind === 'ident') {
442	          if (BUILTIN_CALLS.has(callee.name)) return;
443	          add(view.resolveMethod(callee.name, argc));
444	        } else if (callee.kind === 'member' && callee.object.kind === 'ident' &&
445	                   callee.object.name === 'super') {
446	          let started = false;
447	          for (const { file: f, contract: c } of view.linearized) {
448	            if (!started) { if (c.name === desc.contract) started = true; continue; }
449	            add(findMethodInContract(view, c, f, callee.property, argc));
450	          }
451	        }
452	      });
453	    }
454	  });
455	
456	  // Constructors chain into linearized base constructors.
457	  if (desc.kind === 'constructor') {
458	    let passedSelf = false;
459	    for (const { file: f, contract: c } of view.linearized) {
460	      if (!passedSelf) { if (c.name === desc.contract) passedSelf = true; continue; }
461	      const node = (c.nodes || []).find((fn) => fn.functionKind === 'constructor');
462	      if (node) add({ ...descriptorFor(node, f, c.name, (node.params || []).length), node });
463	    }
464	  }
465	  return edges;
466	}
467	
468	function computeReachability(view) {
469	  // descKey -> entryKey -> chain (descriptors, entry first)
470	  const result = new Map();
471	  const ensure = (k) => {
472	    if (!result.has(k)) result.set(k, new Map());
473	    return result.get(k);
474	  };
475	
476	  for (const entry of view.entries) {
477	    if (!entry.node) continue;
478	    const startChain = [stripNode(entry)];
479	    const queue = [{ desc: entry, chain: startChain }];
480	    const visited = new Set([descKey(entry)]);
481	    ensure(descKey(entry)).set(entryKey(entry), startChain);
482	    while (queue.length) {
483	      const { desc, chain } = queue.shift();
484	      for (const target of collectEdges(view, desc)) {
485	        const tk = descKey(target);
486	        const newChain = [...chain, stripNode(target)];
487	        const slot = ensure(tk);
488	        const prior = slot.get(entryKey(entry));
489	        if (!prior || prior.length > newChain.length) slot.set(entryKey(entry), newChain);
490	        if (!visited.has(tk)) {
491	          visited.add(tk);
492	          queue.push({ desc: target, chain: newChain });
493	        }
494	      }
495	    }
496	  }
497	
498	  for (const m of view.methods.values()) ensure(descKey(m));
499	  return result;
500	}
501	
502	// ---- rule 1: tainted delegatecall target -----------------------------------
503	
504	function buildTaint(view, fnNode) {
505	  const tainted = new Set((fnNode.params || []).map((p) => p.name).filter(Boolean));
506	
507	  const stateVarControllable = (name) => {
508	    // Any mutable storage value feeding a delegatecall target is treated as
509	    // attacker-influenceable ("可控存储值"); constants/immutables are fixed.
510	    const sv = view.stateVars.get(name);
511	    if (!sv) return false;
512	    return !sv.node.isConstant && !sv.node.isImmutable;
513	  };
514	
515	  const isTaintedExpr = (expr) => {
516	    if (!expr) return false;
517	    let bad = false;
518	    walkExpr(expr, (n) => {
519	      if (bad) return;
520	      if (n.kind === 'ident') {
521	        if (tainted.has(n.name) || stateVarControllable(n.name)) bad = true;
522	      } else if (n.kind === 'member' && n.object.kind === 'ident') {
523	        if ((n.object.name === 'msg' && (n.property === 'sender' || n.property === 'data')) ||
524	            (n.object.name === 'tx' && n.property === 'origin')) {
525	          bad = true;
526	        }
527	      }
528	    });
529	    return bad;
530	  };
531	
532	  // Fixed point: locals deriving from tainted sources become tainted.
533	  const stmts = fnNode.body ? fnNode.body.statements : [];
534	  let changed = true;
535	  let guard = 0;
536	  while (changed && guard++ < 20) {
537	    changed = false;
538	    for (const s of stmts) {
539	      walkStatement(s, (st) => {
540	        let names = null;
541	        let value = null;
542	        if (st.kind === 'varDecl' && st.initializer) {
543	          names = st.names || [];
544	          value = st.initializer;
