1083	    const mkFall = (a) => flow(a, null, null, null);
1084	    const dead = () => flow(null, null, null, null);
1085	
1086	    // Walk one frame's effective (modifier-inlined) statements.
1087	    const walk = (desc, frame, pre) => {
1088	      const recList = (list, carryP) => {
1089	        let carry = carryP;
1090	        let ret = null;
1091	        let brk = null;
1092	        let cont = null;
1093	        for (const { stmt, origin } of list) {
1094	          const r = rec(stmt, origin, carry);
1095	          if (r.ret) ret = mergeA(ret, r.ret);
1096	          if (r.brk) brk = mergeA(brk, r.brk);
1097	          if (r.cont) cont = mergeA(cont, r.cont);
1098	          if (r.fall === null) return flow(null, ret, brk, cont);
1099	          carry = r.fall;
1100	        }
1101	        return flow(carry, ret, brk, cont);
1102	      };
1103	
1104	      const rec = (s, origin, carryP) => {
1105	        switch (s.kind) {
1106	          case 'block':
1107	            return recList((s.statements || []).map((stmt) => ({ stmt, origin })), carryP);
1108	          case 'unchecked':
1109	            return rec(s.body, origin, carryP);
1110	
1111	          case 'bodyRegion': {
1112	            // A function-body return resumes the enclosing modifier
1113	            // suffix, so the ret channel becomes fall-through here.
1114	            const r = recList(s.items, carryP);
1115	            return flow(mergeA(r.fall, r.ret), null, r.brk, r.cont);
1116	          }
1117	          case 'modRegion':
1118	            // Returns originating in this modifier's own code escape all
1119	            // remaining suffixes; pass every channel through unchanged.
1120	            return recList(s.items, carryP);
1121	
1122	          case 'if': {
1123	            const preC = mergeA(carryP, atomsOf(s.test, origin, frame, carryP));
1124	            const rt = rec(s.consequent, origin, preC);
1125	            if (!s.alternate) {
1126	              // False-condition path (preC) merges with a falling then.
1127	              const fallParts = [preC];
1128	              if (rt.fall) fallParts.push(rt.fall);
1129	              return flow(mergeA(...fallParts), rt.ret, rt.brk, rt.cont);
1130	            }
1131	            const re = rec(s.alternate, origin, preC);
1132	            return flow(
1133	              mergeA(...[rt.fall, re.fall].filter(Boolean)),
1134	              mergeA(...[rt.ret, re.ret].filter(Boolean)),
1135	              mergeA(...[rt.brk, re.brk].filter(Boolean)),
1136	              mergeA(...[rt.cont, re.cont].filter(Boolean)),
1137	            );
1138	          }
