1140	          case 'while':
1141	          case 'doWhile':
1142	          case 'for':
1143	            return recLoop(s, origin, frame, carryP);
1144	
1145	          case 'try': {
1146	            const preTry = mergeA(carryP, atomsOf(s.externalCall, origin, frame, carryP));
