1148	            const clauses = s.clauses || [];
1149	            const rcList = clauses.map((c) => rec(c, origin, preTry));
1150	            const pick = (chan) =>
1151	              mergeA(...[rb[chan], ...rcList.map((x) => x[chan])].filter(Boolean));
