1153	            // body's exits survive.
1154	            if (clauses.length === 0) return rb;
1155	            return flow(pick('fall'), pick('ret'), pick('brk'), pick('cont'));
1156	          }
1157	
1158	          case 'return': {
1159	            // The returned expression is evaluated before control leaves.
1160	            const atoms = atomsOf(s.expr, origin, frame, carryP);
1161	            return flow(null, mergeA(carryP, atoms), null, null);
1162	          }
1163	
1164	          case 'throw':
1165	            return dead();
1166	
1167	          case 'break':
1168	            return flow(null, null, carryP, null);
1169	          case 'continue':
1170	            return flow(null, null, null, carryP);
1171	
1172	          case 'varDecl':
1173	            return mkFall(mergeA(carryP, atomsOf(s.initializer, origin, frame, carryP)));
1174	
1175	          case 'emit':
1176	            return mkFall(mergeA(carryP, atomsOf(s.expr, origin, frame, carryP)));
1177	
1178	          case 'expression': {
1179	            if (isRevertCall(s.expr)) return dead();
1180	            const atoms = atomsOf(s.expr, origin, frame, carryP);
1181	            const ws = mergeA(carryP, atoms);
1182	            for (const [loc, target] of writesOf(s)) {
1183	              recordWrite(loc, target, origin, frame, ws);
1184	            }
