1190	        }
1191	      };
1192	
1193	      // Loop handling as a monotone fixed point over the set of
1194	      // interactions that may be live when entering the body. Earlier
1195	      // iterations therefore witness later-iteration body writes; the
1196	      // false-test / break exits witness writes after the loop.
1197	      const recLoop = (s, origin, frame, carryP) => {
1198	        let enter = carryP;
1199	        let ret = null;
1200	        let exited = null;
1201	
1202	        if (s.kind === 'for' && s.init) {
1203	          const ri = rec(s.init, origin, enter);
1204	          if (ri.ret) ret = mergeA(ret, ri.ret);
1205	          if (ri.fall === null) return flow(null, ret, null, null);
1206	          enter = ri.fall;
1207	        }
1208	
1209	        const addTest = (c) => s.test ? mergeA(c, atomsOf(s.test, origin, frame, c)) : c;
1210	
1211	        for (let i = 0; i < MAX_LOOP_ITERS; i++) {
1212	          let bodyInput;
1213	          if (s.kind === 'doWhile') {
1214	            bodyInput = enter; // condition is at the bottom
1215	          } else {
1216	            const atTest = addTest(enter);
1217	            exited = mergeA(exited, atTest); // exit via false condition
1218	            bodyInput = atTest;
1219	          }
1220	
1221	          const rb = rec(s.body, origin, bodyInput);
1222	          if (rb.ret) ret = mergeA(ret, rb.ret);
1223	          if (rb.brk) exited = mergeA(exited, rb.brk);
1224	
1225	          // Body fall-through and `continue` feed the next iteration.
1226	          let repeat = mergeA(...[rb.fall, rb.cont].filter(Boolean));
1227	          if (repeat) {
1228	            if (s.kind === 'for' && s.update) {
1229	              repeat = mergeA(repeat, atomsOf(s.update, origin, frame, repeat));
1230	            }
1231	            if (s.test) {
1232	              repeat = addTest(repeat);
1233	              // Bottom/re-test may also be false -> exit carries it.
1234	              exited = mergeA(exited, repeat);
1235	            }
1236	          }
1237	
1238	          const nextEnter = mergeA(enter, repeat || []);
1239	          if (nextEnter.length === enter.length) { enter = nextEnter; break; }
1240	          enter = nextEnter;
1241	        }
