1243	      };
1244	
1245	      return recList(regionItemsOf(desc), pre);
1246	    };
1247	
1248	    return { rootKey, walk, ctorPrefix };
1249	  }
1250	
1251	  // One root walk per method (entries and non-entries alike): a pattern
1252	  // provable only inside an unreachable helper is still reported, then
1253	  // marked reachable=false by the driver.
1254	  for (const root of view.methods.values()) {
1255	    if (!root.node || !root.node.body) continue;
1256	    const rk = descKey(root);
1257	    const frame = { desc: root, depth: 1, rootKey: rk, stack: new Set([rk]) };
1258	    const walker = makeWalker(root);
1259	    const initial = root.kind === 'constructor' ? walker.ctorPrefix(frame, []) : [];
1260	    walker.walk(root, frame, initial);
1261	  }
1262	
1263	  // A storage write with no preceding interaction on any path is not the
1264	  // pattern at all.
1265	  for (const [k, entry] of writes) {
1266	    if (entry.witnesses.size === 0) writes.delete(k);
1267	  }
1268	  return writes;
1269	}
1270	
1271	// ---- driver ----------------------------------------------------------------
1272	
1273	export function analyze(parsedFiles) {
1274	  const registry = new Registry(parsedFiles);
1275	  const views = registry.buildViews();
1276	  const acc = new Map();
1277	
1278	  for (const view of views) {
1279	    const reach = computeReachability(view);
1280	
1281	    for (const desc of view.methods.values()) {
1282	      if (!desc.node || !desc.node.body) continue;
1283	      const wrapped = view.effectiveStatements(desc);
1284	      const reachMap = reach.get(descKey(desc)) || new Map();
1285	
1286	      for (const r of [
1287	        ...runDelegatecallRule(view, desc, wrapped),
1288	        ...runUncheckedCallRule(view, desc, wrapped),
1289	      ]) {
1290	        const key = `${r.ruleId}:${r.origin.file}:${r.location.startOffset}:${r.location.endOffset}`;
1291	        let f = acc.get(key);
1292	        if (!f) {
1293	          f = { ruleId: r.ruleId, severity: RULES[r.ruleId].severity,
1294	            file: r.origin.file, location: r.location, detail: r, entries: new Map() };
1295	          acc.set(key, f);
1296	        }
1297	        // Modifier-originated findings inherit the reachability of the
1298	        // enclosing method (modifier code is inlined into it).
1299	        const effectiveReach = (r.origin.kind === 'modifier') ? reachMap :
1300	          (reach.get(descKey(r.origin)) || reachMap);
1301	        for (const [ek, chain] of effectiveReach.entries()) {
1302	          const prior = f.entries.get(ek);
1303	          if (!prior || prior.chain.length > chain.length) f.entries.set(ek, { chain });
1304	        }
1305	      }
1306	    }
1307	
1308	    // STATE_UPDATE_AFTER_CALL: one path-sensitive, cross-function walk per
1309	    // view. Reachability of an ordered (interaction ... write) path is
1310	    // "an entry reaches the root frame whose walk proved the path".
1311	    for (const wEntry of runStateEngine(view).values()) {
1312	      const key = `STATE_UPDATE_AFTER_CALL:${wEntry.file}:${wEntry.location.startOffset}:${wEntry.location.endOffset}`;
1313	      let f = acc.get(key);
1314	      if (!f) {
1315	        f = {
1316	          ruleId: 'STATE_UPDATE_AFTER_CALL',
1317	          severity: RULES.STATE_UPDATE_AFTER_CALL.severity,
1318	          file: wEntry.file, location: wEntry.location,
1319	          detail: { ruleId: 'STATE_UPDATE_AFTER_CALL', stateVar: wEntry.stateVar },
1320	          kind: 'state',
1321	          cands: [],    // reachable witnesses: {ek, depth, chainWrite, chainInter, wFile, wLoc}
1322	          fallback: [], // {depth, wFile, wLoc} for the unreachable case
1323	        };
