1325	      }
1326	      const reachWrite = reach.get(wEntry.frameKey) || new Map();
1327	      for (const w of wEntry.witnesses.values()) {
1328	        const reachInter = reach.get(w.frameKey) || new Map();
1329	        for (const [rootKey, depth] of w.byRoot) {
1330	          const rootReach = reach.get(rootKey);
1331	          if (rootReach) {
1332	            for (const ek of rootReach.keys()) {
1333	              const chainWrite = reachWrite.get(ek);
1334	              const chainInter = reachInter.get(ek);
