1349	
1350	function locOf(file, loc) {
1351	  return {
1352	    file,
1353	    startLine: loc.startLine,
1354	    startColumn: loc.startColumn,
1355	    endLine: loc.endLine,
1356	    endColumn: loc.endColumn,
1357	  };
1358	}
