1388	    }
1389	    findings.push({
1390	      ruleId: f.ruleId,
1391	      severity: f.severity,
1392	      message,
1393	      location: locOf(f.file, f.location),
1394	      reachable,
1395	      evidence: {
1396	        entryPoints: reachable ? entryPoints : [],
1397	        callChain: reachable ? callChains[0] : [],
1398	      },
1399	    });
1400	  }
1401	  return findings;
1402	}
1403	
1404	// State-update findings carry an `interaction` witness: the external
1405	// interaction that, on the same static path, precedes the storage write.
1406	function finalizeState(f) {
1407	  const d = f.detail;
1408	  const message = `公开入口在外部调用或转账之后写入重入敏感状态 ${d.stateVar}，违反 checks-effects-interactions 顺序`;
1409	
1410	  const entryCmp = (a, b) => {
1411	    if (a.contract !== b.contract) return (a.contract || '') < (b.contract || '') ? -1 : 1;
1412	    if (a.kind !== b.kind) return a.kind < b.kind ? -1 : 1;
1413	    return a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
1414	  };
1415	
1416	  // One row per entry: shortest write chain decides entry order, then the
1417	  // entry identity (matching the generic finalizer's chain ordering).
1418	  const perEntry = new Map();
1419	  for (const c of f.cands) {
1420	    const prev = perEntry.get(c.ek);
1421	    if (!prev ||
1422	        prev.chainWrite.length > c.chainWrite.length ||
1423	        (prev.chainWrite.length === c.chainWrite.length &&
1424	         entryCmp(prev.chainWrite[0], c.chainWrite[0]) > 0)) {
1425	      perEntry.set(c.ek, c);
1426	    }
1427	  }
1428	  const entryRows = [...perEntry.values()].sort((a, b) => {
1429	    if (a.chainWrite.length !== b.chainWrite.length) {
1430	      return a.chainWrite.length - b.chainWrite.length;
1431	    }
1432	    return entryCmp(a.chainWrite[0], b.chainWrite[0]);
1433	  });
1434	
1435	  const entryPoints = [];
1436	  for (const c of entryRows) {
1437	    const e = c.chainWrite[0];
1438	    if (!entryPoints.some((x) => x.name === e.name && x.contract === e.contract &&
1439	                                x.kind === e.kind)) {
1440	      entryPoints.push(e);
1441	    }
1442	  }
1443	  const reachable = entryPoints.length > 0;
1444	
1445	  // Single witness across all (entry, witness) pairs: fewest function
1446	  // frames; ties follow entry order, then the earliest interaction point.
1447	  let chosen = null;
1448	  if (reachable) {
1449	    const entryIndex = (e) =>
1450	      entryPoints.findIndex((x) => x.name === e.name && x.contract === e.contract &&
1451	                                  x.kind === e.kind);
1452	    const ranked = [...f.cands].sort((a, b) => {
1453	      if (a.depth !== b.depth) return a.depth - b.depth;
1454	      const ia = entryIndex(a.chainWrite[0]);
1455	      const ib = entryIndex(b.chainWrite[0]);
1456	      if (ia !== ib) return ia - ib;
1457	      if (a.wFile !== b.wFile) return a.wFile < b.wFile ? -1 : 1;
