1460	    chosen = ranked[0];
1461	  } else {
1462	    const best = new Map();
1463	    for (const x of f.fallback) {
1464	      const k = `${x.wFile}:${x.wLoc.startOffset}`;
1465	      const prior = best.get(k);
1466	      if (!prior || prior.depth > x.depth) best.set(k, x);
1467	    }
