1469	      if (a.depth !== b.depth) return a.depth - b.depth;
1470	      if (a.wFile !== b.wFile) return a.wFile < b.wFile ? -1 : 1;
1471	      return a.wLoc.startOffset - b.wLoc.startOffset;
