1482	    ruleId: f.ruleId,
1483	    severity: f.severity,
1484	    message,
1485	    location: locOf(f.file, f.location),
1486	    reachable,
1487	    evidence: {
1488	      entryPoints: reachable ? entryPoints : [],
1489	      callChain: reachable ? entryRows[0].chainWrite : [],
1490	      interaction,
1491	    },
1492	  };
1493	}
