1	// Zero-dependency test runner. Spawns the CLI as a subprocess so exit
2	// codes and stdout shape are exercised exactly as users see them.
3	
4	import { execFileSync } from 'node:child_process';
5	import fs from 'node:fs';
6	import os from 'node:os';
7	import path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	
10	const __dirname = path.dirname(fileURLToPath(import.meta.url));
11	const BIN = path.join(__dirname, '..', 'bin', 'contract-sentry.js');
12	
13	let passed = 0;
14	let failed = 0;
15	const failures = [];
16	
17	function assert(cond, message) {
18	  if (cond) { passed++; }
19	  else { failed++; failures.push(message); console.error(`  ✗ ${message}`); }
20	}
21	
22	function makeSandbox() {
23	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'contract-sentry-'));
24	  return {
25	    dir,
26	    write(name, content) {
27	      const full = path.join(dir, name);
28	      fs.mkdirSync(path.dirname(full), { recursive: true });
29	      fs.writeFileSync(full, content);
30	      return full;
31	    },
32	    remove() { fs.rmSync(dir, { recursive: true, force: true }); },
33	  };
34	}
35	
36	function run(target) {
37	  try {
38	    const stdout = execFileSync(process.execPath, [BIN, 'audit', target], {
39	      encoding: 'utf8',
40	    });
41	    return { code: 0, json: JSON.parse(stdout), stdout };
42	  } catch (e) {
43	    return {
44	      code: e.status,
45	      json: e.stdout ? JSON.parse(e.stdout) : null,
46	      stdout: e.stdout || '',
47	      stderr: e.stderr || '',
48	    };
49	  }
50	}
51	
52	function rules(findings, id) {
53	  return findings.filter((f) => f.ruleId === id);
54	}
55	
56	// ---------------------------------------------------------------------------
57	
58	function testCleanContract() {
59	  const sb = makeSandbox();
60	  sb.write('clean.sol', `
61	pragma solidity ^0.8.0;
62	contract Safe {
63	    mapping(address => uint256) private balances;
64	    function withdraw(uint256 amount) public {
65	        require(balances[msg.sender] >= amount);
66	        balances[msg.sender] -= amount;
67	        (bool ok, ) = msg.sender.call{value: amount}("");
68	        require(ok, "transfer failed");
69	    }
70	}
71	`);
72	  const r = run(path.join(sb.dir, 'clean.sol'));
73	  assert(r.code === 0, `clean: exit code 0 (got ${r.code})`);
74	  assert(Array.isArray(r.json.files) && r.json.files.length === 1, 'clean: files array');
75	  assert(Array.isArray(r.json.findings), 'clean: findings array present');
76	  const unchecked = rules(r.json.findings, 'UNCHECKED_EXTERNAL_CALL');
77	  assert(unchecked.length === 0, 'clean: require(ok) suppresses UNCHECKED_EXTERNAL_CALL');
78	  const state = rules(r.json.findings, 'STATE_UPDATE_AFTER_CALL');
79	  assert(state.length === 0, 'clean: effects-before-call suppresses STATE_UPDATE_AFTER_CALL');
80	  sb.remove();
81	}
82	
83	function testDelegatecall() {
84	  const sb = makeSandbox();
85	  sb.write('dc.sol', `
86	pragma solidity ^0.8.0;
87	contract DC {
88	    address constant FIXED = address(0x123);
89	    address impl;
90	    function byParam(address target, bytes calldata data) external {
91	        target.delegatecall(data);
92	    }
93	    function byMsgData() external {
94	        impl.delegatecall(msg.data);
95	    }
96	    function bySender() external {
97	        msg.sender.delegatecall("");
98	    }
99	    function fixed(bytes memory data) external {
100	        FIXED.delegatecall(data);
101	    }
102	    function localTaint(address t) external {
103	        address x = t;
104	        address(impl).delegatecall(abi.encode());
105	    }
106	    function hidden(address u) internal {
107	        u.delegatecall("");
108	    }
109	}
110	`);
111	  const r = run(path.join(sb.dir, 'dc.sol'));
112	  assert(r.code === 0, `delegatecall: exit 0 (got ${r.code} ${r.stdout})`);
113	  const hits = rules(r.json.findings, 'DELEGATECALL_UNTRUSTED_TARGET');
114	  const reachableHits = hits.filter((h) => h.reachable);
115	  const unreachableHits = hits.filter((h) => !h.reachable);
116	  const lines = reachableHits.map((h) => h.location.startLine).sort((a, b) => a - b);
117	  assert(lines.join(',') === '7,10,13,20', `delegatecall: expected reachable lines 7,10,13,20 got ${lines}`);
118	  for (const h of reachableHits) {
119	    assert(h.severity === 'high', 'delegatecall: severity high');
120	    assert(h.evidence.entryPoints.length >= 1, 'delegatecall: has entry point evidence');
121	    assert(h.evidence.callChain.length >= 1, 'delegatecall: has call chain evidence');
122	    assert(h.location.startColumn >= 1 && h.location.endColumn >= h.location.startColumn,
123	      'delegatecall: valid 1-based location span');
124	  }
125	  assert(unreachableHits.length === 1 && unreachableHits[0].location.startLine === 23,
126	    `delegatecall: internal-only hidden() unreachable at line 23, got ${unreachableHits.map((h) => h.location.startLine)}`);
127	  const unreach = unreachableHits[0];
128	  if (unreach) {
129	    assert(unreach.evidence.entryPoints.length === 0, 'unreachable: empty entryPoints');
130	    assert(unreach.evidence.callChain.length === 0, 'unreachable: empty callChain');
131	  }
132	  sb.remove();
133	}
134	
135	function testUncheckedCallVariants() {
136	  const sb = makeSandbox();
137	  sb.write('u.sol', `
138	pragma solidity ^0.8.0;
139	contract U {
140	    function bare(address a) public {
141	        a.call("");
142	    }
143	    function checkedRequire(address a) public {
144	        (bool ok,) = a.call("");
145	        require(ok);
146	    }
147	    function checkedIf(address a) public {
148	        (bool ok,) = a.staticcall("");
149	        if (!ok) { revert(); }
150	    }
151	    function orRevert(address a) public returns (bool) {
152	        bool ok;
153	        (ok,) = a.send(1);
154	        ok || revert();
155	        return ok;
156	    }
157	    function transferUnchecked(address payable a) public {
158	        a.transfer(1);
159	    }
160	    function lateUnused(address a) public {
161	        (bool ok,) = a.call("");
162	        uint256 x = 1;
163	        require(x == 1);
164	    }
165	}
166	`);
167	  const r = run(path.join(sb.dir, 'u.sol'));
168	  assert(r.code === 0, `unchecked: exit 0 (got ${r.code})`);
169	  const hits = rules(r.json.findings, 'UNCHECKED_EXTERNAL_CALL');
170	  const lines = hits.map((h) => h.location.startLine).sort((a, b) => a - b);
171	  // Fixture line 1 is blank: bare(5), transferUnchecked(22), lateUnused(25).
172	  assert(lines.join(',') === '5,22,25', `unchecked: expected 5,22,25 got ${lines}`);
173	  for (const h of hits) {
174	    assert(h.severity === 'medium', 'unchecked: severity medium');
175	    assert(h.reachable === true, 'unchecked: public functions reachable');
176	  }
177	  sb.remove();
178	}
179	
180	function testStateUpdate() {
181	  const sb = makeSandbox();
182	  sb.write('s.sol', `
183	pragma solidity ^0.8.0;
184	contract Reentry {
185	    mapping(address => uint256) balances;
186	    uint256 total;
187	    function bad(address to, uint256 v) public {
188	        to.call{value: v}("");
189	        balances[msg.sender] = 0;
190	    }
191	    function good(address to, uint256 v) public {
192	        balances[msg.sender] = 0;
193	        to.call{value: v}("");
194	    }
195	    function transferThenWrite(address payable to) public {
196	        to.transfer(1);
197	        total += 1;
198	    }
199	    function internalOnly(address to) internal {
200	        to.call("");
201	        total = 1;
202	    }
203	}
204	`);
205	  const r = run(path.join(sb.dir, 's.sol'));
206	  assert(r.code === 0, `state: exit 0 (got ${r.code})`);
207	  const hits = rules(r.json.findings, 'STATE_UPDATE_AFTER_CALL');
208	  const lines = hits.map((h) => h.location.startLine).sort((a, b) => a - b);
209	  // Fixture line 1 is blank: bad write(8), transferThenWrite total+=1 (16),
210	  // internalOnly write(20). The internal-helper pattern is reported too
211	  // but is unreachable from any public entry.
212	  assert(lines.join(',') === '8,16,20', `state: expected 8,16,20 got ${lines}`);
213	  assert(hits.every((h) => h.severity === 'high'), 'state: severity high');
214	  // internalOnly must not be an entry finding for the state rule,
215	  // but its call() is still an unchecked call, reachable=false.
216	  const internalUnchecked = rules(r.json.findings, 'UNCHECKED_EXTERNAL_CALL')
217	    .find((f) => f.location.startLine === 19);
218	  assert(internalUnchecked && internalUnchecked.reachable === false,
219	    'state: internal helper call reachable=false');
220	  const internalState = hits.find((h) => h.location.startLine === 20);
221	  assert(internalState && internalState.reachable === false,
222	    'state: internal helper write reported reachable=false');
223	  assert(internalState.evidence.entryPoints.length === 0,
224	    'state: unreachable empty entryPoints');
225	  assert(internalState.evidence.callChain.length === 0,
226	    'state: unreachable empty callChain');
227	  assert(Array.isArray(internalState.evidence.interaction.callChain) &&
228	    internalState.evidence.interaction.callChain.length === 0,
229	    'state: unreachable empty interaction.callChain');
230	  assert(internalState.evidence.interaction.location &&
231	    internalState.evidence.interaction.location.startLine === 19,
232	    'state: unreachable interaction.location retained at call site');
233	  // Reachable findings carry the witness interaction and its chain.
234	  const bad = hits.find((h) => h.location.startLine === 8);
235	  assert(bad.evidence.interaction.location.startLine === 7,
236	    'state: interaction.location points at the preceding call');
237	  assert(bad.evidence.interaction.callChain.length === 1 &&
238	    bad.evidence.interaction.callChain[0].name === 'bad',
239	    'state: interaction.callChain entry to interaction fn');
240	  sb.remove();
