708	  assert(r.code === 0, `multi: exit 0 (got ${r.code} ${r.stdout})`);
709	  const hits = rules(r.json.findings, 'STATE_UPDATE_AFTER_CALL');
710	  // One write source position -> exactly one finding across inheritance views.
711	  assert(hits.length === 1, `multi: single finding for one write got ${hits.length}`);
712	  const f = hits[0];
713	  const names = f.evidence.entryPoints.map((e) => e.name).sort();
714	  assert(names.join(',') === 'viaA,viaB', `multi: both entries collected got ${names}`);
715	  assert(f.evidence.callChain.map((c) => c.name).join('->') === 'viaA->core',
716	    'multi: shortest write chain is primary callChain');
717	  assert(f.evidence.interaction.callChain.map((c) => c.name).join('->') === 'viaA->core',
718	    'multi: interaction chain reaches the shared helper');
719	  sb.remove();
720	}
